save(228,dict(paragraphs=["Kakoli Ghosh writes poetry in English and Bengali and also paints. Published under her name and as ‘Moon Drops’, her work appears in literary journals and international anthologies. GloMag’s contributor note identifies her collections Unfinished and The Bridge, connecting the poet’s literary work with her interest in visual art.","In Kabita Live, her poems give loneliness and memory a physical presence. ‘The Water Of Life’ draws on distilling, bottles and wine stains to explore grief that outlasts attempts to contain it. ‘Slipping into something else’ moves through emptied spaces, ripening fields, flooded nests and bodily images, making change feel at once intimate and unsettling."],sources=[source('GloMag — November–December 2022, contributor note page 153','https://www.ral-m.com/revue/IMG/pdf/glomagnov-dec-_2022.pdf',['Moon Drops pen name; English and Bengali writing; painting; Unfinished (2010), The Bridge (2022)'],'search_index_excerpt; direct PDF retrieval failed'),source('Poetry for Ukraine — Kakoli Ghosh, page 256','https://www.ral-m.com/revue/IMG/pdf/poetry_for_ukraine.pdf',['West Bengal poet using Moon Drops pen name; anthology contribution'],'search_index_excerpt')],identity_match='The Bridge title, bilingual writing and painting match captured biography. Politician Kakoli Ghosh Dastidar search results excluded.',poems_read=[dict(id=218,title='The Water Of Life',basis='Full poem read: distillation, wine, memory, solitude, railway time and lasting stains.'),dict(id=419,title='Slipping into something else',basis='Full poem read: emptiness, seasonal change, paddy fields, uprooted memory, nests and bodily ruins.')],limitations=['Journal contributor notes are author-supplied; no unspecified awards repeated.','PDF access available via indexed excerpts only; no publisher destination verified for a book card.','No inference of personal illness, alcohol use or lived trauma from poetic speakers.'],next_action='Independent author/editor identity and interpretation review; verify book edition links.'))
